/* U1-C70 (D-220): the QC mechanism tree follows the QC component workbook: Major Assembly > Sub Assembly > Component, using the
   workbook names. The approved mechanism codes stay behind every part (jobs, filters, RTG/ES unchanged). Parts that are not in the
   workbook are kept: manual-list parts and other system parts are filed under the matching assembly or their approved mechanism.
   A group (assembly or sub assembly) is a read filter over its positions, like a physical area; it never owns work or history.
   Data: js/qc-hierarchy.js (generated by tools/u1/import_qc_components.py). Synthetic prototype data only. */
window.EQ = window.EQ || {};
(function (EQ) {
  const T = (EQ.qcTree = {});
  const H = () => EQ.qcHierarchy;
  let itemByKey = null, subById = null, groupById = null, order = null;
  const idx = () => {
    if (!itemByKey && H()) {
      itemByKey = new Map(H().items.map((i) => [i.key, i]));
      subById = new Map(H().subgroups.map((s) => [s.id, s]));
      groupById = new Map(H().groups.map((g) => [g.id, g]));
      order = new Map(H().items.map((i, n) => [i.key, n]));
    }
    return !!itemByKey;
  };
  T.item = (key) => (idx() ? itemByKey.get(key) || null : null);
  T.isExcel = (p) => !!(p && T.item(p.key)?.excel);
  /** The workbook hierarchy applies to the QC model family it was made for, once mechanism instances exist. */
  T.applies = (eq) => !!(eq && idx() && eq.typeCode === H().appliesTo.equipmentType && eq.modelCode === H().appliesTo.modelCode && eq.mains.length);
  /** Workbook name for an existing part key (the name replaces the earlier system name), else the given name. */
  T.nameFor = (key, name) => T.item(key)?.name || name;
  /** Position-template rows for the J526A family: workbook and manual parts that the earlier template did not have. */
  T.templateRows = (have) => (idx() ? H().items.filter((i) => !have.includes(i.key) && (i.binding === 'new' || i.modelOnly))
    .map((i) => [i.key, i.code, i.name, i.positionKind, i.uom, null, i.category, i.binding === 'new' ? 'approximate-location' : 'drawing-derived', i.source, i.binding === 'new' ? null : 'model']) : []);
  // 'model' rows keep the record id the model binding already gives these parts (mp-<equipment>-<key>), so no existing id changes

  const cache = new Map();
  /** Tree model of one equipment: groups > sub groups > positions (active and draft; deactivated positions are left out). */
  T.model = function model(eq) {
    if (!T.applies(eq)) return null;
    const ps = EQ.positionsOf(eq.id).filter((p) => p.state !== 'deactivated');
    const sig = ps.length + '|' + eq.subs.length + '|' + ps.reduce((a, p) => a + p.name.length, 0);
    const hit = cache.get(eq.id); if (hit && hit.sig === sig) return hit;
    const place = new Map(), subOfPos = new Map();
    const sp = H().systemPlacement;
    for (const p of ps) {
      const code = eq.subs.find((s) => s.id === p.subId)?.code;
      let sid = T.item(p.key)?.subgroupId || sp.byKey[p.key] || sp.byCode[code] || 'sys-171';
      if (!subById.has(sid)) sid = 'sys-171';
      if (!place.has(sid)) place.set(sid, []);
      place.get(sid).push(p); subOfPos.set(p.id, sid);
    }
    const rank = (p) => (order.has(p.key) ? order.get(p.key) : 1e6);
    const groups = H().groups.map((g) => ({ ...g, subs: H().subgroups.filter((s) => s.groupId === g.id)
      .map((s) => ({ ...s, positions: (place.get(s.id) || []).slice().sort((a, b) => rank(a) - rank(b) || EQ.cmp(a.name, b.name)) }))
      .filter((s) => s.positions.length) })).filter((g) => g.subs.length);
    const res = { sig, groups, subOfPos };
    cache.set(eq.id, res);
    return res;
  };
  T.isGroup = (id) => idx() && (groupById.has(id) || subById.has(id));
  T.kindOf = (id) => (idx() ? (groupById.has(id) ? 'group' : subById.has(id) ? 'subgroup' : null) : null);
  T.def = (id) => (idx() ? groupById.get(id) || subById.get(id) || null : null);
  T.label = (id) => T.def(id)?.name || id;
  /** Group and sub group of a position (for breadcrumbs and tree expansion). */
  T.pathOf = (eq, posId) => {
    const m = T.model(eq); const sid = m && m.subOfPos.get(posId);
    return sid ? [subById.get(sid).groupId, sid] : [];
  };
  T.parentOf = (id) => subById?.get(id)?.groupId || null;
  /** Position ids of a group or sub group of one equipment; optionally workbook items only. */
  T.positionIds = (eq, id, excelOnly) => {
    const m = T.model(eq); if (!m) return [];
    const out = [];
    for (const g of m.groups) for (const s of g.subs) if (g.id === id || s.id === id) for (const p of s.positions) if (!excelOnly || T.isExcel(p)) out.push(p.id);
    return out;
  };
  T.counts = (eq) => {
    const m = T.model(eq); if (!m) return { all: 0, excel: 0 };
    let all = 0, excel = 0;
    for (const g of m.groups) for (const s of g.subs) for (const p of s.positions) { all += 1; if (T.isExcel(p)) excel += 1; }
    return { all, excel };
  };
})(window.EQ);
